<main class="admin-shell"><aside class="admin-sidebar"><a class="brand" href="<?= base_url('admin') ?>"><span class="brand-mark">S</span><span>EUPHORIA <strong>OPS</strong></span></a><div class="admin-nav"><span class="eyebrow">COMMAND</span><a href="<?= base_url('admin') ?>">Overview</a><a href="<?= base_url('admin/events') ?>">Events</a><a href="<?= base_url('admin/registrations') ?>">Registrations</a><a class="admin-nav-active" href="<?= base_url('admin/attendance') ?>">Attendance</a></div><a href="<?= base_url('logout') ?>" class="admin-logout">Sign out</a></aside><section class="admin-content"><div class="admin-topbar"><div><span class="eyebrow accent">ENTRY OPERATIONS</span><h1>Live attendance</h1></div><a class="button button-yellow" href="<?= base_url('scanner') ?>">Open scanner ↗</a></div><div class="admin-panel"><div class="panel-heading"><div><span class="eyebrow">RECENT SCANS</span><h2><?= count($entries) ?> entries logged</h2></div><span class="status status-success">LIVE</span></div><div class="table-scroll"><table class="data-table"><thead><tr><th>Time</th><th>Participant</th><th>Registration</th><th>Event</th><th>Gate</th><th>Status</th></tr></thead><tbody><?php foreach ($entries as $entry): ?><tr data-testid="attendance-table-row"><td class="mono"><?= esc(date('H:i',strtotime($entry['entry_time']))) ?></td><td><strong><?= esc($entry['participant_name']) ?></strong></td><td class="mono"><?= esc($entry['registration_id']) ?></td><td><?= esc($entry['event_name']) ?></td><td><?= esc($entry['gate_name'] ?: '—') ?></td><td><span class="<?= status_class($entry['status']) ?>"><?= esc(strtoupper($entry['status'])) ?></span></td></tr><?php endforeach ?></tbody></table></div></div></section></main>